{
  "schema_version": "1.0",
  "domain_id": "workflow_0b95eb1629b5b4fc71a0982c54620a97",
  "version": 0,
  "title": "Equipment Loan Request Review",
  "goal": "Review an equipment loan request and decide whether it can join the collection queue or needs the desk manager’s decision. Record the review status and reason.",
  "input_fields": [
    {
      "field_id": "borrower_type",
      "label": "Borrower Type",
      "type": "string",
      "description": "The type of the borrower requesting the loan, typically EMPLOYEE or CONTRACTOR.",
      "required": true
    },
    {
      "field_id": "requested_loan_days",
      "label": "Requested Loan Days",
      "type": "number",
      "description": "The number of days requested for the equipment loan.",
      "required": true
    },
    {
      "field_id": "equipment_available",
      "label": "Equipment Available",
      "type": "boolean",
      "description": "Checkbox indicating if the requested equipment is available.",
      "required": true
    },
    {
      "field_id": "sponsor_confirmed",
      "label": "Sponsor Confirmed",
      "type": "boolean",
      "description": "Checkbox indicating if the loan sponsor has confirmed the request.",
      "required": true
    }
  ],
  "state_fields": [
    {
      "field_id": "review_status",
      "label": "Review Status",
      "type": "string",
      "description": "The current status of the loan request review.",
      "required": true
    },
    {
      "field_id": "reason",
      "label": "Reason",
      "type": "string",
      "description": "The recorded justification or reason for the review outcome status.",
      "required": true
    }
  ],
  "actions": [
    {
      "action_id": "queue_collection",
      "label": "Ready for Collection",
      "description": "Mark the request as ready for collection and add to the queue.",
      "effects": [
        {
          "field_id": "review_status",
          "value": "READY_FOR_COLLECTION"
        },
        {
          "field_id": "reason",
          "value": "Employee request meets standard loan requirements"
        }
      ],
      "terminal": true
    },
    {
      "action_id": "hold_request",
      "label": "Hold Request",
      "description": "Hold request for desk manager's decision or missing information.",
      "effects": [
        {
          "field_id": "review_status",
          "value": "HELD"
        },
        {
          "field_id": "reason",
          "value": "Requires desk manager decision, missing information, or is a contractor request"
        }
      ],
      "terminal": true
    }
  ],
  "rules": [
    {
      "rule_id": "approve_employee_loan",
      "priority": 1,
      "statement": "An EMPLOYEE request may be marked READY_FOR_COLLECTION when requested loan days are from 1 to 5 inclusive, equipment available is Yes, and sponsor confirmed is Yes.",
      "when": {
        "all": [
          {
            "field_id": "borrower_type",
            "operator": "eq",
            "value": "EMPLOYEE"
          },
          {
            "field_id": "requested_loan_days",
            "operator": "gte",
            "value": 1
          },
          {
            "field_id": "requested_loan_days",
            "operator": "lte",
            "value": 5
          },
          {
            "field_id": "equipment_available",
            "operator": "eq",
            "value": true
          },
          {
            "field_id": "sponsor_confirmed",
            "operator": "eq",
            "value": true
          }
        ],
        "any": []
      },
      "action_id": "queue_collection",
      "source_refs": [
        {
          "source_id": "src_1478e0c98965c1c3085a467625e68e76",
          "version_hash": "e558dbcf12531bf51a06124e6575ef80ebe9c12948e0956db2aa3e1a0d159028",
          "locator": "line:7",
          "quote": "An EMPLOYEE request may be marked READY_FOR_COLLECTION when requested loan days are from 1 to 5 inclusive, equipment available is Yes, and sponsor confirmed is Yes."
        }
      ],
      "approved_by": null
    },
    {
      "rule_id": "hold_long_loan",
      "priority": 2,
      "statement": "A request for more than 5 days requires the desk manager's decision and must remain HELD.",
      "when": {
        "all": [
          {
            "field_id": "requested_loan_days",
            "operator": "gt",
            "value": 5
          }
        ],
        "any": []
      },
      "action_id": "hold_request",
      "source_refs": [
        {
          "source_id": "src_1478e0c98965c1c3085a467625e68e76",
          "version_hash": "e558dbcf12531bf51a06124e6575ef80ebe9c12948e0956db2aa3e1a0d159028",
          "locator": "line:8",
          "quote": "A request for more than 5 days requires the desk manager's decision and must remain HELD, even when equipment is available and the sponsor has confirmed."
        }
      ],
      "approved_by": null
    },
    {
      "rule_id": "hold_invalid_days",
      "priority": 3,
      "statement": "If requested loan days are less than 1, keep the request HELD.",
      "when": {
        "all": [
          {
            "field_id": "requested_loan_days",
            "operator": "lt",
            "value": 1
          }
        ],
        "any": []
      },
      "action_id": "hold_request",
      "source_refs": [
        {
          "source_id": "src_1478e0c98965c1c3085a467625e68e76",
          "version_hash": "e558dbcf12531bf51a06124e6575ef80ebe9c12948e0956db2aa3e1a0d159028",
          "locator": "line:9",
          "quote": "If a required value is missing, a checkbox is No, the borrower type is unknown, or requested loan days are less than 1, keep the request HELD"
        }
      ],
      "approved_by": null
    }
  ],
  "default_action_id": "hold_request",
  "source_hashes": {
    "src_1478e0c98965c1c3085a467625e68e76": "e558dbcf12531bf51a06124e6575ef80ebe9c12948e0956db2aa3e1a0d159028"
  }
}

{
  "rules": [
    {
      "rule_id": "approve_contractor_loan",
      "priority": 1,
      "statement": "CONTRACTOR requests may join the same collection queue as EMPLOYEE requests when requested loan days are from 1 to 5 inclusive, equipment available is Yes, and sponsor confirmed is Yes.",
      "when": {
        "all": [
          {
            "field_id": "borrower_type",
            "operator": "eq",
            "value": "CONTRACTOR"
          },
          {
            "field_id": "requested_loan_days",
            "operator": "gte",
            "value": 1
          },
          {
            "field_id": "requested_loan_days",
            "operator": "lte",
            "value": 5
          },
          {
            "field_id": "equipment_available",
            "operator": "eq",
            "value": true
          },
          {
            "field_id": "sponsor_confirmed",
            "operator": "eq",
            "value": true
          }
        ],
        "any": []
      },
      "action_id": "queue_collection",
      "approved_by": null
    }
  ]
}
